package main

import (
 "crypto/md5"
 "crypto/rand"
 "crypto/subtle"
 "encoding/hex"
 "encoding/json"
 "flag"
 "fmt"
 "log"
 "net"
 "os"
 "os/signal"
 "regexp"
 "strconv"
 "strings"
 "sync"
 "syscall"
 "time"
)
type Config struct { Listen string `json:"listen"`; Domain string `json:"domain"`; Users map[string]string `json:"users"`; RegistrationSeconds int `json:"registration_seconds"` }
type Registration struct { Address *net.UDPAddr; Contact string; Expires time.Time }
type Route struct { Address *net.UDPAddr; Expires time.Time }
type PBX struct { conn *net.UDPConn; cfg Config; mu sync.Mutex; regs map[string]Registration; routes map[string]Route; nonce string }
var userRE=regexp.MustCompile(`(?i)sip:([^@;> ]+)`)
func newPBX(c Config,conn *net.UDPConn)*PBX { b:=make([]byte,16); _,_=rand.Read(b); if c.RegistrationSeconds<=0 {c.RegistrationSeconds=300};return &PBX{conn:conn,cfg:c,regs:map[string]Registration{},routes:map[string]Route{},nonce:hex.EncodeToString(b)} }
func splitSIP(raw string)(string,[][2]string,string) { raw=strings.ReplaceAll(raw,"\r\n","\n");parts:=strings.SplitN(raw,"\n\n",2); lines:=strings.Split(parts[0],"\n");if len(lines)==0{return "",nil,""}; headers:=make([][2]string,0,len(lines));for _,l:=range lines[1:] { if len(l)>0 && (l[0]==' '||l[0]=='\t')&&len(headers)>0 {headers[len(headers)-1][1]+=" "+strings.TrimSpace(l);continue};i:=strings.IndexByte(l,':');if i>0 {headers=append(headers,[2]string{strings.TrimSpace(l[:i]),strings.TrimSpace(l[i+1:])})} };body:="";if len(parts)>1 {body=parts[1]};return lines[0],headers,body }
func header(h [][2]string,k string)string {for _,p:=range h {if strings.EqualFold(p[0],k) {return p[1]}};return ""}
func headers(h [][2]string,k string)[]string {var out []string;for _,p:=range h {if strings.EqualFold(p[0],k) {out=append(out,p[1])}};return out}
func serialize(first string,h [][2]string,body string)[]byte {var s strings.Builder;s.WriteString(first+"\r\n");for _,p:=range h {if strings.EqualFold(p[0],"Content-Length") {continue};s.WriteString(p[0]+": "+p[1]+"\r\n")};fmt.Fprintf(&s,"Content-Length: %d\r\n\r\n",len(body));s.WriteString(body);return []byte(s.String())}
func sipUser(s string)string {m:=userRE.FindStringSubmatch(s);if len(m)>1{return m[1]};return ""}
func method(first string)string {p:=strings.Fields(first);if len(p)>0{return strings.ToUpper(p[0])};return ""}
func status(first string)bool {return strings.HasPrefix(first,"SIP/2.0 ")}
func randomHex(n int)string {b:=make([]byte,n);_,_=rand.Read(b);return hex.EncodeToString(b)}
func (p *PBX) send(dst *net.UDPAddr,b []byte){_,err:=p.conn.WriteToUDP(b,dst);if err!=nil{log.Printf("send %s: %v",dst,err)}}
func (p *PBX) reply(dst *net.UDPAddr,req [][2]string,code int,reason string,extra [][2]string) {h:=make([][2]string,0,10);for _,v:=range headers(req,"Via"){h=append(h,[2]string{"Via",v})};for _,k:=range []string{"From","To","Call-ID","CSeq"}{if v:=header(req,k);v!="" {if k=="To"&& !strings.Contains(strings.ToLower(v),";tag="){v+=";tag=pbx"};h=append(h,[2]string{k,v})}};h=append(h,extra...);p.send(dst,serialize(fmt.Sprintf("SIP/2.0 %d %s",code,reason),h,""))}
func parseAuth(s string)map[string]string {r:=map[string]string{};s=strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(s),"Digest"));for len(s)>0 {s=strings.TrimLeft(s," ,");i:=strings.IndexByte(s,'=');if i<1 {break};k:=strings.TrimSpace(s[:i]);s=strings.TrimSpace(s[i+1:]);var v string;if strings.HasPrefix(s,"\""){s=s[1:];j:=strings.IndexByte(s,'"');if j<0{break};v=s[:j];s=s[j+1:]}else{j:=strings.IndexByte(s,',');if j<0 {v=s;s=""}else{v=s[:j];s=s[j:]}};r[strings.ToLower(k)]=v};return r}
func md5hex(s string)string {b:=md5.Sum([]byte(s));return hex.EncodeToString(b[:])}
func (p *PBX) authenticate(h [][2]string,username,verb string)bool {a:=parseAuth(header(h,"Authorization"));pass,ok:=p.cfg.Users[username];if !ok||a["username"]!=username||a["nonce"]!=p.nonce||a["realm"]!=p.cfg.Domain||!strings.EqualFold(a["algorithm"],"MD5")&&a["algorithm"]!=""{return false};uri:=a["uri"];if uri==""{return false};ha1:=md5hex(username+":"+p.cfg.Domain+":"+pass);ha2:=md5hex(verb+":"+uri);expected:="";if a["qop"]=="auth" {if a["nc"]==""||a["cnonce"]==""{return false};expected=md5hex(ha1+":"+p.nonce+":"+a["nc"]+":"+a["cnonce"]+":auth:"+ha2)}else if a["qop"]=="" {expected=md5hex(ha1+":"+p.nonce+":"+ha2)}else{return false};return subtle.ConstantTimeCompare([]byte(strings.ToLower(a["response"])),[]byte(expected))==1 }
func (p *PBX) handle(src *net.UDPAddr,packet []byte){first,h,body:=splitSIP(string(packet));if first==""{return};if status(first){p.handleResponse(src,first,h,body);return};m:=method(first);if header(h,"Via")==""{return};if m=="REGISTER"{p.register(src,h);return};if m=="OPTIONS" {p.reply(src,h,200,"OK",nil);return};if m!="INVITE"&&m!="ACK"&&m!="BYE"&&m!="CANCEL"&&m!="INFO"&&m!="UPDATE"&&m!="REFER"&&m!="NOTIFY"{p.reply(src,h,405,"Method Not Allowed",nil);return};from:=sipUser(header(h,"From"));to:=sipUser(first);if to=="" {to=sipUser(header(h,"To"))};p.mu.Lock();sender,exists:=p.regs[from];target,found:=p.regs[to];now:=time.Now();validSender:=exists&&now.Before(sender.Expires)&&sender.Address.String()==src.String();validTarget:=found&&now.Before(target.Expires);p.mu.Unlock();if !validSender {if m!="ACK" {p.reply(src,h,403,"Forbidden - register first",nil)};return};if !validTarget {if m!="ACK" {p.reply(src,h,404,"Extension Not Registered",nil)};return};fields:=strings.Fields(first);if len(fields)<3 {return};fields[1]=target.Contact;first=strings.Join(fields," ");branch:="z9hG4bK"+randomHex(10);host:=p.conn.LocalAddr().(*net.UDPAddr).IP.String();if host=="0.0.0.0"||host=="::" {host=localIPFor(target.Address)};via:=fmt.Sprintf("SIP/2.0/UDP %s:%d;branch=%s",host,p.conn.LocalAddr().(*net.UDPAddr).Port,branch);h=append([][2]string{{"Via",via}},h...);if m!="ACK" {p.mu.Lock();p.routes[branch]=Route{Address:src,Expires:time.Now().Add(2*time.Minute)};p.mu.Unlock()};p.send(target.Address,serialize(first,h,body));log.Printf("%s %s -> %s",m,from,to)}
func localIPFor(dst *net.UDPAddr)string {c,e:=net.DialUDP("udp",nil,dst);if e!=nil{return "127.0.0.1"};defer c.Close();return c.LocalAddr().(*net.UDPAddr).IP.String()}
func (p *PBX) handleResponse(src *net.UDPAddr,first string,h [][2]string,body string) {via:=header(h,"Via");i:=strings.Index(via,"branch=");if i<0 {return};branch:=strings.SplitN(via[i+7:],";",2)[0];p.mu.Lock();r,ok:=p.routes[branch];if ok&&time.Now().After(r.Expires){ok=false;delete(p.routes,branch)};p.mu.Unlock();if !ok{return};skipped:=false;clean:=make([][2]string,0,len(h));for _,v:=range h {if strings.EqualFold(v[0],"Via")&&!skipped {skipped=true;continue};clean=append(clean,v)};p.send(r.Address,serialize(first,clean,body))}
func (p *PBX) register(src *net.UDPAddr,h [][2]string){user:=sipUser(header(h,"To"));if _,ok:=p.cfg.Users[user];!ok {p.reply(src,h,403,"Unknown Extension",nil);return};if !p.authenticate(h,user,"REGISTER"){p.reply(src,h,401,"Unauthorized",[][2]string{{"WWW-Authenticate",fmt.Sprintf("Digest realm=\"%s\", nonce=\"%s\", algorithm=MD5, qop=\"auth\"",p.cfg.Domain,p.nonce)}});return};contact:=header(h,"Contact");if strings.Contains(contact,",") {contact=strings.SplitN(contact,",",2)[0]};secs:=p.cfg.RegistrationSeconds;if v:=header(h,"Expires");v!=""{if n,e:=strconv.Atoi(v);e==nil{secs=n}};if i:=strings.Index(strings.ToLower(contact),";expires=");i>=0{if n,e:=strconv.Atoi(strings.SplitN(contact[i+9:],";",2)[0]);e==nil{secs=n}};if secs<0 {secs=0};if secs>3600 {secs=3600};p.mu.Lock();if secs==0||contact=="*"{delete(p.regs,user)}else{uri:=strings.TrimSpace(contact);if start:=strings.Index(uri,"<");start>=0 {uri=uri[start+1:];if end:=strings.Index(uri,">");end>=0{uri=uri[:end]}}else{uri=strings.SplitN(uri,";",2)[0]};if !strings.HasPrefix(strings.ToLower(uri),"sip:"){p.mu.Unlock();p.reply(src,h,400,"Invalid Contact",nil);return};p.regs[user]=Registration{src,uri,time.Now().Add(time.Duration(secs)*time.Second)}};p.mu.Unlock();extra:=[][2]string{{"Expires",strconv.Itoa(secs)}};if secs>0 {extra=append(extra,[2]string{"Contact",contact})};p.reply(src,h,200,"OK",extra);log.Printf("registration %s at %s expires %ds",user,src,secs)}
func main(){cfgPath:=flag.String("config","config.json","configuration file");flag.Parse();b,e:=os.ReadFile(*cfgPath);if e!=nil{log.Fatal(e)};var c Config;if e=json.Unmarshal(b,&c);e!=nil{log.Fatal(e)};if c.Listen==""{c.Listen=":5060"};if c.Domain==""{c.Domain="pbx.local"};if len(c.Users)<2 {log.Fatal("configure at least two SIP users")};addr,e:=net.ResolveUDPAddr("udp",c.Listen);if e!=nil{log.Fatal(e)};conn,e:=net.ListenUDP("udp",addr);if e!=nil{log.Fatal(e)};defer conn.Close();p:=newPBX(c,conn);log.Printf("Pbx_simple SIP/UDP listening %s, extensions %d",conn.LocalAddr(),len(c.Users));signals:=make(chan os.Signal,1);signal.Notify(signals,os.Interrupt,syscall.SIGTERM);go func(){<-signals;conn.Close()}();buf:=make([]byte,65535);for{n,src,e:=conn.ReadFromUDP(buf);if e!=nil {return};pkt:=append([]byte(nil),buf[:n]...);p.handle(src,pkt);p.mu.Lock();for u,r:=range p.regs {if time.Now().After(r.Expires){delete(p.regs,u)}};for k,r:=range p.routes {if time.Now().After(r.Expires){delete(p.routes,k)}};p.mu.Unlock()}}
